                    Spacer(modifier = Modifier.height(12.dp))

                    ToggleRow(
                        label = "Uppercase (A-Z)",
                        checked = uiState.useUppercase,
                        onCheckedChange = { generatorViewModel.toggleUppercase(it) }
                    )
                    ToggleRow(
