                        onCheckedChange = { generatorViewModel.toggleDigits(it) }
                    )
                    ToggleRow(
                        label = "Symbols (!@#\$%...)",
                        checked = uiState.useSymbols,
                        onCheckedChange = { generatorViewModel.toggleSymbols(it) }
                    )
                }
            }

            if (uiState.history.isNotEmpty()) {
                Spacer(modifier = Modifier.height(16.dp))
                Card(
