                Icons.Rounded.Visibility
            } else {
                Icons.Filled.VisibilityOff
            },
            modifier = Modifier.align(Alignment.CenterVertically),
            color = MaterialTheme.colorScheme.tertiary
        ) {
            showPassword = !showPassword
        }

    }
}

