private fun ListItem(
    details: CardDetails,
    update: (CardOption) -> Unit,
    modifier: Modifier = Modifier,
) {
    Card(
        colors = CardDefaults.cardColors(
            containerColor = colorScheme.secondaryContainer,
        ),
        modifier = modifier,
    ) {
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            modifier = Modifier.fillMaxSize(),
        ) {
            Column(
                modifier = Modifier
                    .padding(horizontal = 8.dp, vertical = 16.dp)
                    .weight(1f),
            ) {
                val hasEnoughContrast = colorScheme.primary
                    .hasEnoughContrast(colorScheme.secondaryContainer)

                val titleColor =
                    if (hasEnoughContrast) colorScheme.primary
                    else colorScheme.onSecondaryContainer

                Text(
                    text = details.room,
                    style = MaterialTheme.typography.headlineSmall,
                    fontWeight = FontWeight.Light,
                    letterSpacing = 1.sp,
                    color = titleColor,
                    modifier = Modifier.padding(start = 16.dp),
                )

                Column(
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth(),
                ) {
                    details.options.forEach { option ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(16.dp),
                            modifier = Modifier
                                .clip(MaterialTheme.shapes.medium)
                                .toggleable(
                                    value = option.selected,
                                    onValueChange = {
                                        update(option.copy(selected = it))
                                    },
                                    role = Role.Checkbox,
                                )
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp)
                                .weight(1f),
                        ) {
                            Checkbox(
                                checked = option.selected,
                                onCheckedChange = null,
                            )

                            Column {
                                Text(
                                    text = option.title,
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.Light,
                                )
                                Text(
                                    text = option.description,
                                    style = MaterialTheme.typography.bodySmall,
                                    fontWeight = FontWeight.Light,
                                    fontStyle = FontStyle.Italic,
                                )
                            }
                        }
                    }
                }
            }

            Image(
                painter = painterResource(details.image),
                contentDescription = details.options.first().title,
                modifier = Modifier
                    .align(Alignment.Bottom)
                    .fillMaxHeight(0.6f)
                    .padding(end = 8.dp),
            )
        }
    }
}

