    Box(
        contentAlignment = Alignment.Center,
        modifier = modifier
            .size(42.dp)
            .clip(CircleShape)
            .background(containerColor)
            .clickable(enabled = !isSelected, onClick = onClick),
    ) {
        Icon(
            imageVector = contrast.icon(),
            contentDescription = contrast.name(),
            tint = contentColor,
            modifier = Modifier.padding(6.dp),
        )
    }
}

