@Composable
fun CoinIconWithSyncProgress(
    token: Token,
    syncingProgress: SyncingProgress,
    failedIconVisible: Boolean,
    onClickSyncError: (() -> Unit)?,
    boxSize: Dp = 40.dp,
    iconSize: Dp = 32.dp
) {
    val transition = rememberInfiniteTransition(label = "sync_rotation")
    val rotate by transition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(
            animation = tween(
                durationMillis = 1100,
                easing = LinearEasing
            )
        ),
        label = "rotation"
    )

    val progress = syncingProgress.progress
    val iconAlpha = if (syncingProgress.type == null) 1f else 0.3f
    val leah = ComposeAppTheme.colors.leah
    val circleColor = ComposeAppTheme.colors.steel10

    Box(
        modifier = Modifier
            .size(boxSize)
            .drawBehind {
                when (syncingProgress.type) {
                    SyncingProgressType.ProgressWithRing -> {
                        val progressF = ((progress ?: 0.0).coerceAtLeast(10.0) / 100.0).toFloat()
                        val angle = 360f * progressF

                        inset(-1.dp.toPx()) {
                            drawArc(
                                color = circleColor,
                                startAngle = 0f,
                                sweepAngle = 360f,
                                useCenter = false,
                                style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round)
                            )
                            rotate(degrees = -90f) {
                                drawArc(
                                    color = leah,
                                    startAngle = 0f,
                                    sweepAngle = angle,
                                    useCenter = false,
                                    style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round)
                                )
                            }
                        }
                    }

                    SyncingProgressType.Spinner -> {
                        inset(-1.dp.toPx()) {
                            drawArc(
                                color = circleColor,
                                startAngle = 0f,
                                sweepAngle = 360f,
                                useCenter = false,
                                style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round)
                            )
                            rotate(degrees = rotate) {
                                drawArc(
                                    color = leah,
                                    startAngle = 0f,
                                    sweepAngle = -120f,
                                    useCenter = false,
                                    style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round)
                                )
                            }
                        }
                    }

                    null -> {
                        // No progress indicator
                    }
                }
            },
        contentAlignment = Alignment.Center
    ) {
        if (failedIconVisible) {
            val clickableModifier = if (onClickSyncError != null) {
                Modifier.clickable(
                    interactionSource = remember { MutableInteractionSource() },
                    indication = ripple(
                        bounded = false,
                        radius = 20.dp
                    ),
                    onClick = onClickSyncError
                )
            } else {
                Modifier
            }

            Image(
                modifier = Modifier
                    .size(iconSize)
                    .then(clickableModifier),
                painter = painterResource(id = R.drawable.ic_attention_24),
                contentDescription = "coin icon",
                colorFilter = ColorFilter.tint(ComposeAppTheme.colors.lucian)
            )
        } else {
            CoinImage(
                token = token,
                modifier = Modifier
                    .size(iconSize)
                    .alpha(iconAlpha)
            )
        }

        if (syncingProgress.type == SyncingProgressType.ProgressWithRing) {
            syncingProgress.progress?.let {
                SyncProgressText("${formatProgressPercent(it)}%")
            }
        }
    }
}

