@Composable
fun PostItem(
    post: Post,
    user: User,
    onImageClick: () -> Unit,
    onMoreClick: () -> Unit,
) {
    var likes by remember {
        mutableIntStateOf(post.likeCount)
    }
    var isExpanded by remember {
        mutableStateOf(false)
    }
    Column(Modifier.padding(vertical = 4.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            CircularImage(
                imageUrl = user.profileImage,
                imageSize = 40.dp,
                modifier = Modifier
                    .padding(vertical = 8.dp, horizontal = 16.dp)
                    .clickable {
                        onImageClick()
                    }
            )
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(vertical = 4.dp)
            ) {
                Text(user.name)
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    "location",
                    fontSize = 12.sp,
                    color = Color.Gray,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            Spacer(modifier = Modifier.width(8.dp))
            IconButton(onClick = {
                onMoreClick()
            }) {
                Icon(
                    imageVector = Icons.Default.MoreVert,
                    contentDescription = null,
                    Modifier.padding(8.dp)
                )
            }
        }
        PostImage(imageUrl = post.postImage)
        Spacer(modifier = Modifier.height(4.dp))
        Row(
            horizontalArrangement = Arrangement.SpaceEvenly,
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(start = 8.dp)
        ) {
            var isFavorite by remember { mutableStateOf(false) }
            var isBookmarked by remember { mutableStateOf(false) }
            ToggleIconButton(
                enableTint = Color.Red,
                enableIcon = rememberVectorPainter(image = Icons.Filled.Favorite),
                disableIcon = rememberVectorPainter(image = Icons.Filled.FavoriteBorder),
                initialState = isFavorite
            ) {
                if (it)
                    likes++
                else
                    likes--
                isFavorite = !isFavorite
            }
            IconButton(onClick = {
                //no-op
            }) {
                Icon(
                    painterResource(id = R.drawable.ic_comment),
                    contentDescription = null,
                    Modifier.padding(vertical = 8.dp)
                )
            }
            IconButton(onClick = { /*no-op*/ }) {
                Icon(
                    Icons.Default.Send,
                    contentDescription = null,
                    modifier = Modifier.padding( vertical = 8.dp)
                )
            }

            Spacer(modifier = Modifier.weight(1f))
            ToggleIconButton(
                enableTint = MaterialTheme.colorScheme.onBackground,
                enableIcon = painterResource(id = R.drawable.ic_bookmark),
                disableIcon = painterResource(id = R.drawable.ic_bookmark_border),
                initialState = isBookmarked
            ) {
                isBookmarked = !isBookmarked
            }
        }
        AnimatedContent(
            targetState = likes,
            transitionSpec = { fadeIn() + scaleIn() togetherWith fadeOut() + scaleOut() },
            label = "likes"
        ) {
            Text(
                "$it likes",
                Modifier.padding(horizontal = 16.dp)
            )
        }

        Spacer(modifier = Modifier.height(4.dp))
        Text(
            text = post.caption,
            modifier = Modifier
                .animateContentSize()
                .padding(horizontal = 16.dp)
                .clickable {
                    isExpanded = !isExpanded
                },
            maxLines = if (isExpanded) 5 else 2,
            overflow = TextOverflow.Ellipsis
        )
    }
}

