    var iconSize by remember(app.key) { mutableIntStateOf(app.listIconSizeDp) }
    var showIcon by remember(app.key) { mutableStateOf(app.showLabel) }
    var iconShape by remember(app.key) { mutableStateOf(app.iconShape) }
    var rotation by remember(app.key) { mutableFloatStateOf(app.rotationDeg) }

    EditDialogShell(
        title = info.label,
        onDismiss = onDismiss,
        onSave = {
            onSave(app.copy(
                listTextSizeSp = textSize,
                listIconSizeDp = iconSize,
                showLabel = showIcon,
                iconShape = iconShape,
                rotationDeg = rotation
            ))
        }
    ) {
        OptionLabel("text size — ${textSize}sp")
        Slider(
            value = textSize.toFloat(),
            onValueChange = { textSize = it.toInt() },
            valueRange = 12f..24f,
            steps = 11,
            colors = sliderColors,
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(Modifier.height(12.dp))

        OptionLabel("icon size — ${iconSize}dp")
        Slider(
            value = iconSize.toFloat(),
            onValueChange = { iconSize = it.toInt() },
            valueRange = 20f..64f,
            steps = 10,
            colors = sliderColors,
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(Modifier.height(12.dp))

        OptionLabel("icon shape")
        Spacer(Modifier.height(4.dp))
        IconShapePicker(selected = iconShape, onSelect = { iconShape = it })

        Spacer(Modifier.height(12.dp))

