fun MainScreen(
    modifier: Modifier = Modifier,
    fontFamily: FontFamily,
    useCustom: Boolean,
    isDarkMode: Boolean,
    onDarkModeChecked: (Boolean) -> Unit,
    fullBackground: Boolean,
    onFullBackgroundChecked: (Boolean) -> Unit,
    onSwitchChange: (Boolean) -> Unit,
    onSuccessClick: () -> Unit,
    onErrorClick: () -> Unit,
    onWarningClick: () -> Unit,
