                                            contentDescription = null,
                                        )
                                    },
                                    modifier = Modifier.clickable {
                                        val todo = moveTodoTarget
                                        if (todo != null) {
                                            viewModel.copyTodo(todo, target.uri)
                                        }
                                        moveTodoTarget = null
                                        showCopyOption = false
                                    },
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    Scaffold(
